// Appends Texas TDLR ids 432-451 and Shampooing & Conditioning ids 452-481
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/barber-questions.js')

function fmt(q, topic, topic_es, psi_topic, psi_topic_es) {
  return `  { id: ${q.id}, topic: ${topic}, topic_es: ${topic_es}, psi_topic: ${psi_topic}, psi_topic_es: ${psi_topic_es}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

// Texas TDLR: internal topic != psi_topic
const tdT = `"Texas TDLR Laws & Regulations"`, tdTes = `"Leyes y Regulaciones de Texas TDLR"`
const tdPsi = `"Licensing & Regulation"`, tdPsiEs = `"Licencias y Regulaciones"`

const tdQ = [
  { id: 432, question: "Client records in a barbershop must be kept confidential because:", question_es: "Los registros de clientes en una barbería deben mantenerse confidenciales porque:", options: ["They contain personal health information that the client has a right to privacy over, and unauthorized disclosure may violate Texas privacy laws", "TDLR requires records to be destroyed after each visit", "Client records are the property of the state of Texas", "Records are confidential only if the client is a minor"], options_es: ["Contienen información de salud personal sobre la que el cliente tiene derecho a privacidad, y la divulgación no autorizada puede violar las leyes de privacidad de Texas", "TDLR requiere que los registros sean destruidos después de cada visita", "Los registros de clientes son propiedad del estado de Texas", "Los registros son confidenciales solo si el cliente es menor de edad"], correct: 0, explanation: "Client records (including health history, chemical service records, and patch test results) contain personal information. Texas privacy expectations require that this information not be disclosed without client consent. Unauthorized disclosure can lead to civil liability." },
  { id: 433, question: "Under Texas law, the primary difference between an 'employee' and an 'independent contractor' booth renter in a barbershop is:", question_es: "Según la ley de Texas, la diferencia principal entre un 'empleado' y un 'contratista independiente' arrendatario de espacio en una barbería es:", options: ["Control and financial independence: the shop owner controls employees' schedules/methods while a booth renter operates their own business independently and pays rent to use the space", "A booth renter does not need a barber license; an employee does", "Employees can perform any service; booth renters are limited to haircuts only", "Both are legally identical under Texas barbering law"], options_es: ["Control e independencia financiera: el dueño de la barbería controla los horarios/métodos de los empleados mientras que un arrendatario de espacio opera su propio negocio de forma independiente y paga alquiler para usar el espacio", "Un arrendatario de espacio no necesita licencia de barbero; un empleado sí", "Los empleados pueden realizar cualquier servicio; los arrendatarios de espacio están limitados solo a cortes de cabello", "Ambos son legalmente idénticos bajo la ley de barbería de Texas"], correct: 0, explanation: "The key legal distinction is the degree of control. Employees are directed by the employer (hours, methods, pricing). Booth renters are independent contractors who run their own business, set their own hours/prices, and pay the shop owner rent for the use of the space." },
  { id: 434, question: "Texas allows a barber to also hold a cosmetology license. This dual licensee:", question_es: "Texas permite que un barbero también tenga una licencia de cosmetología. Este titular de doble licencia:", options: ["May perform both barbering and cosmetology services, but only within the scope of each respective license", "May perform any service from either scope without any limitation", "Must choose one license and surrender the other", "Must work in different locations for each license"], options_es: ["Puede realizar tanto servicios de barbería como de cosmetología, pero solo dentro del alcance de cada licencia respectiva", "Puede realizar cualquier servicio de cualquier alcance sin ninguna limitación", "Debe elegir una licencia y entregar la otra", "Debe trabajar en diferentes ubicaciones para cada licencia"], correct: 0, explanation: "A barber may hold both a Class A Barber license and a cosmetology license. They may perform all services covered by both licenses, but must comply with the rules and scope applicable to each license type. Both licenses must be current and displayed." },
  { id: 435, question: "A consumer who believes a Texas barber or barbershop violated the law can:", question_es: "Un consumidor que cree que un barbero o barbería de Texas violó la ley puede:", options: ["File a complaint with TDLR, which will investigate the allegation and take action if a violation is found", "Only sue in civil court — TDLR does not investigate consumer complaints", "Report the violation to the Texas Attorney General's Consumer Protection Division only", "Post a negative review online to warn others — no official process exists"], options_es: ["Presentar una queja ante TDLR, que investigará la alegación y tomará acción si se encuentra una violación", "Solo demandar en un tribunal civil — TDLR no investiga quejas de consumidores", "Reportar la violación solo a la División de Protección al Consumidor del Fiscal General de Texas", "Publicar una reseña negativa en línea para advertir a otros — no existe ningún proceso oficial"], correct: 0, explanation: "TDLR has a consumer complaint process. Members of the public can file written complaints about licensed barbers or barbershops. TDLR investigates and, when violations are substantiated, takes administrative action (fines, license suspension or revocation)." },
  { id: 436, question: "A barber who has a communicable disease that could be transmitted through barbering services:", question_es: "Un barbero que tiene una enfermedad contagiosa que podría transmitirse a través de los servicios de barbería:", options: ["Must refrain from performing services that could expose clients to the disease until they have recovered or their physician determines they are no longer contagious", "May continue working but must wear extra gloves", "Must notify TDLR immediately and will automatically lose their license", "Is only prohibited from services if the client requests documentation of the barber's health"], options_es: ["Debe abstenerse de realizar servicios que puedan exponer a los clientes a la enfermedad hasta que se haya recuperado o su médico determine que ya no es contagioso", "Puede continuar trabajando pero debe usar guantes adicionales", "Debe notificar a TDLR de inmediato y automáticamente perderá su licencia", "Solo se le prohíbe los servicios si el cliente solicita documentación de la salud del barbero"], correct: 0, explanation: "Barbers with communicable diseases must not perform services while contagious. This protects client health. Wearing gloves alone is insufficient if the disease can be transmitted through other routes. The barber must be cleared by a medical professional before returning to services." },
  { id: 437, question: "The continuing education requirement for Texas barbers is designed to:", question_es: "El requisito de educación continua para los barberos de Texas está diseñado para:", options: ["Ensure licensed barbers maintain current knowledge of sanitation, safety, and professional skills throughout their career", "Collect revenue for TDLR through CE provider fees", "Prepare barbers for a more advanced license level", "Replace the original licensing examination every renewal cycle"], options_es: ["Garantizar que los barberos con licencia mantengan conocimiento actualizado de saneamiento, seguridad y habilidades profesionales a lo largo de su carrera", "Recaudar ingresos para TDLR a través de las tarifas de proveedores de EC", "Preparar a los barberos para un nivel de licencia más avanzado", "Reemplazar el examen de licencia original en cada ciclo de renovación"], correct: 0, explanation: "Continuing education (CE) requirements exist to ensure barbers stay updated on sanitation standards, new techniques, safety practices, and regulatory changes. CE protects clients by keeping barbers' knowledge current throughout their careers." },
  { id: 438, question: "Safety Data Sheets (SDS) must be maintained in a barbershop because:", question_es: "Las Hojas de Datos de Seguridad (SDS) deben mantenerse en una barbería porque:", options: ["They contain chemical safety information (hazards, safe handling, first aid) for all chemical products used in the shop, required by OSHA regulations for worker safety", "TDLR requires SDS for marketing materials only", "They are the same as the client service record forms", "Only barbershops with more than 5 employees must keep SDS"], options_es: ["Contienen información de seguridad química (peligros, manejo seguro, primeros auxilios) para todos los productos químicos usados en la barbería, requerido por las regulaciones de OSHA para la seguridad de los trabajadores", "TDLR requiere SDS solo para materiales de marketing", "Son iguales que los formularios de registro de servicio del cliente", "Solo las barberías con más de 5 empleados deben mantener SDS"], correct: 0, explanation: "OSHA's Hazard Communication Standard requires that SDS (formerly MSDS) be maintained and accessible to all employees for every hazardous chemical used in the workplace. Barbershops use multiple chemicals (color, bleach, relaxers, perms) requiring SDS documentation." },
  { id: 439, question: "A Texas barbershop must maintain which of the following records on-site?", question_es: "Una barbería de Texas debe mantener cuáles de los siguientes registros en el establecimiento?", options: ["Current TDLR licenses for all barbers working at the location, plus the establishment license", "Federal tax returns for the past 5 years", "OSHA Form 300 (workplace injury log) for shops with fewer than 10 employees", "TDLR does not require any on-site documentation"], options_es: ["Licencias actuales de TDLR para todos los barberos que trabajan en la ubicación, más la licencia del establecimiento", "Declaraciones de impuestos federales de los últimos 5 años", "Formulario OSHA 300 (registro de lesiones en el lugar de trabajo) para tiendas con menos de 10 empleados", "TDLR no requiere ninguna documentación en el establecimiento"], correct: 0, explanation: "Texas barbershops must keep current, valid TDLR licenses for every barber practicing at that location, plus the barbershop establishment license. All must be displayed in a conspicuous location." },
  { id: 440, question: "Under Texas TDLR rules, barbershop owner-operators are responsible for:", question_es: "Según las reglas de TDLR de Texas, los propietarios-operadores de barberías son responsables de:", options: ["Ensuring the entire establishment complies with all TDLR sanitation and safety rules, even when violations are committed by individual barbers at the shop", "Only their own individual practice — violations by employed barbers are solely those barbers' responsibility", "Establishing TDLR rules independently for their specific establishment", "Reporting all client transactions to TDLR monthly"], options_es: ["Garantizar que todo el establecimiento cumpla con todas las reglas de saneamiento y seguridad de TDLR, incluso cuando las violaciones son cometidas por barberos individuales en la barbería", "Solo su práctica individual — las violaciones de los barberos empleados son solo responsabilidad de esos barberos", "Establecer reglas de TDLR de forma independiente para su establecimiento específico", "Reportar todas las transacciones de clientes a TDLR mensualmente"], correct: 0, explanation: "Shop owners/operators have an affirmative duty to ensure their establishment operates in compliance with all applicable TDLR rules. Both the establishment license and the individual barber licenses can be subject to enforcement action for violations." },
  { id: 441, question: "A Texas barber examination candidate who fails the written exam may:", question_es: "Un candidato al examen de barbero de Texas que reprueba el examen escrito puede:", options: ["Retake the exam after paying the reexamination fee — there is no limit on retake attempts, but each requires payment", "Only retake the exam once before needing to repeat barber school", "Never retake the exam; they must apply for an apprentice permit instead", "Retake the exam for free within 30 days of failure"], options_es: ["Volver a tomar el examen después de pagar la tarifa de reexaminación — no hay límite en los intentos de repetición, pero cada uno requiere pago", "Solo volver a tomar el examen una vez antes de necesitar repetir la escuela de barbería", "Nunca volver a tomar el examen; deben solicitar un permiso de aprendiz en su lugar", "Volver a tomar el examen gratis dentro de los 30 días del fracaso"], correct: 0, explanation: "Candidates who fail the PSI written or practical examination may retake the failed portion upon payment of the reexamination fee. There is no statutory limit on the number of retake attempts, though each attempt requires registration and payment." },
  { id: 442, question: "A Texas barber's license may be suspended or revoked by TDLR for:", question_es: "La licencia de un barbero de Texas puede ser suspendida o revocada por TDLR por:", options: ["Fraud, intentional misrepresentation, practicing while impaired, gross incompetence, violating sanitation rules, or other conduct demonstrating unfitness to practice", "Only failing to pay the renewal fee on time", "Any complaint submitted by a client, regardless of its merit", "Refusing to join a professional barber association"], options_es: ["Fraude, tergiversación intencional, práctica mientras está bajo la influencia de sustancias, incompetencia grave, violación de las reglas de saneamiento u otra conducta que demuestre incapacidad para ejercer", "Solo por no pagar la tarifa de renovación a tiempo", "Cualquier queja presentada por un cliente, independientemente de su mérito", "Negarse a unirse a una asociación profesional de barberos"], correct: 0, explanation: "TDLR may suspend or revoke a barber license for: fraud in obtaining the license, practicing while impaired, gross incompetence, habitual violations of sanitation rules, criminal conviction, or any conduct showing unfitness to practice. Due process protections apply." },
  { id: 443, question: "A Texas barber who moves their practice to a new barbershop location must:", question_es: "Un barbero de Texas que muda su práctica a una nueva ubicación de barbería debe:", options: ["Ensure their individual license information is updated with TDLR if their address changes, and verify the new location has a valid barbershop establishment license", "Obtain a new barber license for the new location", "Notify all former clients within 30 days by certified mail", "Submit their previous shop's inspection report to TDLR"], options_es: ["Asegurarse de que la información de su licencia individual esté actualizada con TDLR si su dirección cambia, y verificar que la nueva ubicación tenga una licencia de establecimiento de barbería válida", "Obtener una nueva licencia de barbero para la nueva ubicación", "Notificar a todos los clientes anteriores dentro de los 30 días por correo certificado", "Enviar el informe de inspección de su barbería anterior a TDLR"], correct: 0, explanation: "A barber's individual license follows the person, not the location. When moving to a new shop, the barber must update their address with TDLR (within 30 days), and must work only in locations that hold a valid barbershop establishment license." },
  { id: 444, question: "Which of the following acts is specifically PROHIBITED in a Texas barbershop under TDLR regulations?", question_es: "¿Cuál de los siguientes actos está específicamente PROHIBIDO en una barbería de Texas según las regulaciones de TDLR?", options: ["Using any implement that has not been properly disinfected between clients", "Providing services to clients over 65 years of age without a waiver", "Charging different prices for the same service based on length of the service", "Offering appointment scheduling through a mobile app"], options_es: ["Usar cualquier implemento que no haya sido desinfectado correctamente entre clientes", "Proporcionar servicios a clientes mayores de 65 años sin una exención", "Cobrar diferentes precios por el mismo servicio según la duración del servicio", "Ofrecer programación de citas a través de una aplicación móvil"], correct: 0, explanation: "Using an implement that has not been properly disinfected between clients is explicitly prohibited under Texas barbershop sanitation rules. Reusing contaminated implements is a direct health violation and among the most commonly cited infractions during TDLR inspections." },
  { id: 445, question: "TDLR's administrative penalty schedule for barbershop violations:", question_es: "El cronograma de sanciones administrativas de TDLR para las violaciones de barberías:", options: ["Assigns penalty amounts based on the severity of the violation and whether it is a first or repeat offense", "Applies a flat $1,000 fine for every violation regardless of type", "Only applies to barbershop owners, not individual barbers", "Is set exclusively by the Texas Legislature and cannot be changed by TDLR"], options_es: ["Asigna montos de penalidad basados en la gravedad de la violación y si es una primera o repetida infracción", "Aplica una multa fija de $1,000 por cada violación independientemente del tipo", "Solo aplica a los propietarios de barberías, no a los barberos individuales", "Es establecido exclusivamente por la Legislatura de Texas y no puede ser cambiado por TDLR"], correct: 0, explanation: "TDLR uses a structured penalty schedule that considers: severity of the violation (risk to public health), the number of prior violations, and other mitigating or aggravating factors. More serious or repeat violations carry higher penalties." },
  { id: 446, question: "A Texas barber school (barber college) must be licensed by:", question_es: "Una escuela de barbería de Texas (colegio de barbería) debe ser licenciada por:", options: ["TDLR, which inspects and approves barber schools to ensure they meet curriculum and facility standards", "The Texas Education Agency (TEA)", "The Texas Higher Education Coordinating Board (THECB) only", "The U.S. Department of Education for all programs"], options_es: ["TDLR, que inspecciona y aprueba las escuelas de barbería para garantizar que cumplan con los estándares de currículo y facilidades", "La Agencia de Educación de Texas (TEA)", "Solo la Junta Coordinadora de Educación Superior de Texas (THECB)", "El Departamento de Educación de los EE.UU. para todos los programas"], correct: 0, explanation: "Barber schools in Texas must hold a TDLR barbershop school license. TDLR establishes curriculum requirements, facility standards, and instructor qualifications. Only hours earned at TDLR-licensed schools count toward the licensing requirement." },
  { id: 447, question: "A Texas barbershop inspection that reveals a critical sanitation violation (such as using unsterilized cutting instruments) typically results in:", question_es: "Una inspección de barbería de Texas que revela una violación crítica de saneamiento (como el uso de instrumentos de corte no esterilizados) típicamente resulta en:", options: ["A notice of violation with a required correction timeframe, potential fines, and a follow-up inspection to verify compliance", "Immediate permanent closure of the barbershop with no appeal", "A warning letter with no further action unless a client is harmed", "Mandatory retraining of all staff before any action is taken"], options_es: ["Un aviso de violación con un plazo de corrección requerido, posibles multas y una inspección de seguimiento para verificar el cumplimiento", "Cierre permanente inmediato de la barbería sin apelación", "Una carta de advertencia sin ninguna acción adicional a menos que un cliente sea perjudicado", "Reentrenamiento obligatorio de todo el personal antes de que se tome cualquier acción"], correct: 0, explanation: "When critical violations are found, TDLR issues a notice of violation specifying the violation, required corrective action, and the timeframe to comply. Fines may be assessed. A follow-up inspection verifies correction. Immediate closure is typically reserved for imminent health hazards." },
  { id: 448, question: "Under Texas TDLR rules, what must a barber do if they suspect a client has a communicable scalp condition?", question_es: "Según las reglas de TDLR de Texas, ¿qué debe hacer un barbero si sospecha que un cliente tiene una condición contagiosa del cuero cabelludo?", options: ["Refuse the service politely, advise the client to see a physician, and do not perform any service that could spread the condition to others", "Perform the service with extra gloves and sanitize heavily afterward", "Report the client's name to the local health department immediately", "Require the client to provide a doctor's note before any future service"], options_es: ["Rechazar el servicio cortésmente, aconsejar al cliente que consulte a un médico y no realizar ningún servicio que pueda difundir la condición a otros", "Realizar el servicio con guantes adicionales y sanitizar fuertemente después", "Reportar el nombre del cliente al departamento de salud local de inmediato", "Requerir que el cliente proporcione una nota médica antes de cualquier servicio futuro"], correct: 0, explanation: "When a communicable scalp condition is suspected (ringworm, impetigo, head lice, etc.), the barber must decline to perform the service and advise the client to seek medical treatment. Performing service could spread the condition to other clients through the barber's tools." },
  { id: 449, question: "Which statement accurately describes the difference between Texas cosmetology and Texas barbering licensing?", question_es: "¿Qué declaración describe con precisión la diferencia entre las licencias de cosmetología y barbería de Texas?", options: ["Barbering includes shaving and razor work on the face/neck as part of its core scope; cosmetology traditionally does not include this; each has a separate licensing structure under Texas law", "Both licenses allow exactly the same services with no distinction", "Cosmetology requires more education hours than barbering in Texas", "Barbering is regulated locally while cosmetology is regulated by the state"], options_es: ["La barbería incluye el afeitado y el trabajo con navaja en el rostro/cuello como parte de su alcance principal; la cosmetología tradicionalmente no incluye esto; cada una tiene una estructura de licencias separada bajo la ley de Texas", "Ambas licencias permiten exactamente los mismos servicios sin distinción", "La cosmetología requiere más horas de educación que la barbería en Texas", "La barbería está regulada localmente mientras que la cosmetología está regulada por el estado"], correct: 0, explanation: "The key distinction is scope: barbering includes razor shaving of the face and neck, which is not in the cosmetology scope. Both are state-regulated by TDLR. Both have 1,500-hour education minimums. Dual licensees may perform services from both scopes." },
  { id: 450, question: "A Texas barber who has allowed their license to expire and is still practicing:", question_es: "Un barbero de Texas que ha dejado vencer su licencia y continúa ejerciendo:", options: ["Is practicing without a license, which is a violation subject to TDLR fines and possible prohibition from future licensure", "Has a 6-month grace period during which they may continue to practice without penalty", "Simply needs to pay the renewal fee and is otherwise unrestricted", "Must take the full barber exam again before practicing"], options_es: ["Está practicando sin licencia, lo que es una violación sujeta a multas de TDLR y posible prohibición de futuras licencias", "Tiene un período de gracia de 6 meses durante el cual puede continuar practicando sin penalidad", "Simplemente necesita pagar la tarifa de renovación y de lo contrario no tiene restricciones", "Debe tomar el examen de barbero completo nuevamente antes de practicar"], correct: 0, explanation: "Practicing after a license has expired constitutes practicing without a license — a violation of Texas law. TDLR may impose fines for each day of unlicensed practice. The barber must renew the license (potentially with a late fee) before they may legally practice again." },
  { id: 451, question: "Texas TDLR may require a barber license applicant to submit to a criminal background check because:", question_es: "TDLR de Texas puede requerir que un solicitante de licencia de barbero se someta a una verificación de antecedentes criminales porque:", options: ["Texas law requires TDLR to determine whether an applicant's criminal history may disqualify them from licensure or poses a risk to public safety", "All applicants must pay a federal background check fee regardless of their history", "Background checks are only required for applicants who disclose prior convictions", "TDLR shares background check results with the applicant's future employer automatically"], options_es: ["La ley de Texas requiere que TDLR determine si el historial criminal de un solicitante puede descalificarlo de la licencia o representa un riesgo para la seguridad pública", "Todos los solicitantes deben pagar una tarifa de verificación de antecedentes federales independientemente de su historial", "Las verificaciones de antecedentes solo se requieren para solicitantes que divulgan condenas previas", "TDLR comparte los resultados de la verificación de antecedentes con el futuro empleador del solicitante automáticamente"], correct: 0, explanation: "Texas requires criminal background checks for barber license applicants. TDLR evaluates the results under Texas Occupations Code Chapter 53, which provides a framework for determining when criminal history is relevant to licensure and establishing a process for applicants to request a pre-determination of eligibility." },
]

// First 30 Shampooing & Conditioning (ids 452–481)
const scT = `"Shampooing & Conditioning"`, scTes = `"Champú y Acondicionamiento"`

const scQ = [
  { id: 452, question: "The primary purpose of shampooing a client's hair before a barbering service is:", question_es: "El propósito principal del lavado del cabello de un cliente antes de un servicio de barbería es:", options: ["To remove dirt, oil (sebum), product buildup, and environmental debris from the scalp and hair shaft, preparing the hair for the service", "To permanently alter the hair's protein structure for better manageability", "To apply medication for scalp conditions identified during consultation", "To reduce the time needed for chemical services by pre-softening the hair"], options_es: ["Eliminar la suciedad, el aceite (sebo), la acumulación de productos y los residuos ambientales del cuero cabelludo y el eje del cabello, preparando el cabello para el servicio", "Alterar permanentemente la estructura proteínica del cabello para una mejor manejabilidad", "Aplicar medicación para las condiciones del cuero cabelludo identificadas durante la consulta", "Reducir el tiempo necesario para los servicios químicos pre-suavizando el cabello"], correct: 0, explanation: "Shampooing cleanses the scalp and hair by removing sebum, dirt, dead skin cells, product buildup, and pollutants. A clean scalp and hair create the optimal foundation for cutting, styling, and chemical services." },
  { id: 453, question: "A 'surfactant' is the active cleansing ingredient in shampoo. How does it work?", question_es: "Un 'surfactante' es el ingrediente limpiador activo en el champú. ¿Cómo funciona?", options: ["Each surfactant molecule has a water-attracting (hydrophilic) end and an oil-attracting (hydrophobic/lipophilic) end — the lipophilic end attaches to oils on the hair while the hydrophilic end allows water to rinse the oil-surfactant complex away", "Surfactants work by chemically dissolving protein bonds in the hair to release trapped dirt", "They work by raising the pH of the hair above 9 to force the cuticle open and release debris", "Surfactants use ultraviolet light activated during shampooing to break down oil molecules"], options_es: ["Cada molécula de surfactante tiene un extremo que atrae el agua (hidrofílico) y un extremo que atrae el aceite (hidrofóbico/lipofílico) — el extremo lipofílico se adhiere a los aceites en el cabello mientras que el extremo hidrofílico permite que el agua enjuague el complejo aceite-surfactante", "Los surfactantes funcionan disolviendo químicamente los enlaces de proteínas en el cabello para liberar la suciedad atrapada", "Funcionan elevando el pH del cabello por encima de 9 para forzar la apertura de la cutícula y liberar los residuos", "Los surfactantes usan luz ultravioleta activada durante el lavado para descomponer las moléculas de aceite"], correct: 0, explanation: "Surfactants are amphiphilic molecules — one end is hydrophilic (attracted to water) and the other is hydrophobic/lipophilic (attracted to oils). They surround oil droplets (micelles), suspending dirt and oil in water so they can be rinsed away." },
  { id: 454, question: "The pH range of most professional shampoos falls within:", question_es: "El rango de pH de la mayoría de los champús profesionales cae dentro de:", options: ["4.5 to 5.5 (slightly acidic), close to the natural pH of healthy hair and scalp", "7 to 8 (slightly alkaline) to gently open the cuticle", "9 to 10 (strongly alkaline) for maximum cleansing power", "1 to 2 (strongly acidic) to tighten the cuticle"], options_es: ["4.5 a 5.5 (ligeramente ácido), cercano al pH natural del cabello y cuero cabelludo saludables", "7 a 8 (ligeramente alcalino) para abrir suavemente la cutícula", "9 a 10 (fuertemente alcalino) para máximo poder de limpieza", "1 a 2 (fuertemente ácido) para tensar la cutícula"], correct: 0, explanation: "Healthy hair and scalp have a natural pH of approximately 4.5–5.5 (slightly acidic). Most professional shampoos are formulated in this same range to work effectively while respecting the hair's natural acid mantle and keeping the cuticle relatively smooth." },
  { id: 455, question: "A clarifying (chelating) shampoo is used primarily to:", question_es: "Un champú clarificante (quelante) se usa principalmente para:", options: ["Remove heavy product buildup (styling products, silicones, mineral deposits from hard water) that regular shampoo cannot fully remove", "Add moisture and protein back into dry, damaged hair", "Enhance and deposit artificial color during the shampoo step", "Reduce dandruff caused by Malassezia yeast on the scalp"], options_es: ["Eliminar la acumulación pesada de productos (productos para peinar, siliconas, depósitos minerales del agua dura) que el champú regular no puede eliminar completamente", "Agregar humedad y proteína al cabello seco y dañado", "Realzar y depositar color artificial durante el paso del champú", "Reducir la caspa causada por la levadura Malassezia en el cuero cabelludo"], correct: 0, explanation: "Clarifying shampoos contain chelating agents (like EDTA) that bind to mineral ions and remove stubborn buildup from hard water, chlorine, and styling products. They cleanse more aggressively than regular shampoos but should not be used too frequently as they can dry the hair." },
  { id: 456, question: "A moisturizing shampoo is formulated for clients with:", question_es: "Un champú humectante está formulado para clientes con:", options: ["Dry, brittle, or chemically treated hair that needs extra hydration", "Oily hair and scalp that require extra degreasing power", "Hair with excessive product buildup from heavy pomades", "Tightly coiled hair that needs the curl pattern loosened"], options_es: ["Cabello seco, quebradizo o tratado químicamente que necesita hidratación extra", "Cabello y cuero cabelludo grasosos que requieren mayor poder desengrasante", "Cabello con exceso de acumulación de productos por pomadas pesadas", "Cabello muy rizado que necesita que el patrón de rizo se afloje"], correct: 0, explanation: "Moisturizing shampoos contain humectants and conditioning agents (glycerin, panthenol, natural oils) that attract and retain moisture in the hair. They are ideal for dry, brittle, chemically damaged, or coarse hair types that need hydration during the cleansing step." },
  { id: 457, question: "Before shampooing a client, the barber should perform a scalp analysis to:", question_es: "Antes de lavar el cabello de un cliente, el barbero debe realizar un análisis del cuero cabelludo para:", options: ["Identify any scalp conditions (abrasions, lesions, parasites, inflammation, or disease) that would contraindicate the service or require a specific product choice", "Determine the exact brand of shampoo the client prefers", "Calculate how many ounces of shampoo the service will require", "Identify the client's natural hair color level"], options_es: ["Identificar cualquier condición del cuero cabelludo (abrasiones, lesiones, parásitos, inflamación o enfermedad) que contraindique el servicio o requiera una elección específica de producto", "Determinar la marca exacta de champú que el cliente prefiere", "Calcular cuántas onzas de champú requerirá el servicio", "Identificar el nivel de color de cabello natural del cliente"], correct: 0, explanation: "A pre-shampoo scalp analysis identifies contraindications (wounds, contagious conditions) and guides product selection. If the scalp shows open lesions, abrasions, or signs of a communicable condition, the service must be refused to protect both client and barber." },
  { id: 458, question: "The correct draping procedure before a shampoo service is:", question_es: "El procedimiento correcto de colocación de capa antes de un servicio de champú es:", options: ["Place a towel around the client's neck as a base layer, then drape the shampoo cape over it — the towel absorbs water and protects the skin while the cape shields clothing", "Place the shampoo cape directly on bare skin with no towel", "Drape only with a stylist smock and skip the neck towel for shampoos", "Use the haircut cape for all services including shampooing"], options_es: ["Colocar una toalla alrededor del cuello del cliente como capa base, luego colocar la capa de champú sobre ella — la toalla absorbe el agua y protege la piel mientras la capa protege la ropa", "Colocar la capa de champú directamente sobre la piel desnuda sin toalla", "Cubrir solo con una bata de estilista y omitir la toalla de cuello para los champús", "Usar la capa de corte de cabello para todos los servicios incluyendo el lavado"], correct: 0, explanation: "Proper shampoo draping begins with a freshly laundered neck towel (or neck strip) placed directly against the client's skin, followed by the waterproof shampoo cape over it. This protects the client's clothing and skin while absorbing water." },
  { id: 459, question: "The ideal water temperature for shampooing a client's hair is:", question_es: "La temperatura ideal del agua para lavar el cabello de un cliente es:", options: ["Warm (comfortably warm, not hot) — warm water opens the cuticle slightly for effective cleansing without causing scalp discomfort or burns", "Cold water to keep the cuticle closed during shampooing", "Very hot water to maximize product penetration and cleaning power", "Alternating between very hot and very cold water for the 'contrast rinse' effect"], options_es: ["Tibia (cómodamente tibia, no caliente) — el agua tibia abre la cutícula ligeramente para una limpieza efectiva sin causar malestar en el cuero cabelludo ni quemaduras", "Agua fría para mantener la cutícula cerrada durante el lavado", "Agua muy caliente para maximizar la penetración del producto y el poder de limpieza", "Alternando entre agua muy caliente y muy fría para el efecto de 'enjuague de contraste'"], correct: 0, explanation: "Warm water is the standard for shampooing. It is comfortable for the client, effectively loosens product buildup and sebum, and provides a good environment for the shampoo to lather. Very hot water can cause scalp irritation or burns; cold water reduces cleansing effectiveness." },
  { id: 460, question: "The barber should wet the hair thoroughly before applying shampoo because:", question_es: "El barbero debe mojar completamente el cabello antes de aplicar el champú porque:", options: ["Thorough wetting distributes the shampoo evenly, activates the lather, and ensures the product reaches the scalp — dry hair absorbs the shampoo before it can work on the scalp", "Dry application of shampoo to unwetted hair produces stronger cleansing action", "Wetting prevents the shampoo from stripping natural oils", "TDLR requires that all hair be pre-wetted as part of sanitation compliance"], options_es: ["La humectación completa distribuye el champú de manera uniforme, activa la espuma y garantiza que el producto llegue al cuero cabelludo — el cabello seco absorbe el champú antes de que pueda trabajar en el cuero cabelludo", "La aplicación en seco del champú en cabello no húmedo produce una acción de limpieza más fuerte", "La humectación evita que el champú elimine los aceites naturales", "TDLR requiere que todo el cabello esté pre-húmedo como parte del cumplimiento de saneamiento"], correct: 0, explanation: "Pre-wetting ensures even distribution of the shampoo and proper lather development. Dry hair will absorb product unevenly, resulting in insufficient scalp cleansing and wasted product. Thorough saturation is needed for effective surfactant action." },
  { id: 461, question: "Scalp manipulations during shampooing are performed using:", question_es: "Las manipulaciones del cuero cabelludo durante el lavado se realizan usando:", options: ["The pads of the fingers (not the fingernails), using circular or rotary movements to stimulate the scalp and loosen debris", "The fingernails in firm back-and-forth scrubbing motions", "A scalp brush with stiff bristles pressed firmly against the head", "The palms of both hands in a flat pressing motion with no movement"], options_es: ["Las yemas de los dedos (no las uñas), usando movimientos circulares o giratorios para estimular el cuero cabelludo y aflojar los residuos", "Las uñas en movimientos firmes de frotamiento de ida y vuelta", "Un cepillo de cuero cabelludo con cerdas rígidas presionado firmemente contra la cabeza", "Las palmas de ambas manos en un movimiento de presión plana sin movimiento"], correct: 0, explanation: "Scalp massage during shampooing is performed with the finger pads using gentle circular or rotary motions. Fingernails must not be used — they scratch the scalp and create micro-abrasions that increase infection risk." },
  { id: 462, question: "Scalp massage during shampooing provides which physiological benefit?", question_es: "El masaje del cuero cabelludo durante el lavado proporciona qué beneficio fisiológico?", options: ["Stimulates blood circulation to the scalp, bringing oxygen and nutrients to the hair follicles while also relaxing the client", "Permanently strengthens the hair shaft by mechanically compressing the cortex", "Opens the follicle opening to allow shampoo to enter the hair root", "Prevents the formation of new dandruff by mechanically removing Malassezia"], options_es: ["Estimula la circulación sanguínea en el cuero cabelludo, llevando oxígeno y nutrientes a los folículos pilosos al tiempo que relaja al cliente", "Fortalece permanentemente el eje del cabello comprimiendo mecánicamente el córtex", "Abre la apertura del folículo para permitir que el champú entre en la raíz del cabello", "Previene la formación de nueva caspa eliminando mecánicamente la Malassezia"], correct: 0, explanation: "Scalp massage increases blood flow (circulation) to the scalp, delivering more oxygen and nutrients to the follicles. It also relaxes muscle tension and provides a pleasurable experience for the client. It does not strengthen the hair shaft or permanently affect follicle structure." },
  { id: 463, question: "A medicated shampoo is designed to:", question_es: "Un champú medicado está diseñado para:", options: ["Treat specific scalp conditions such as dandruff, seborrheic dermatitis, or psoriasis using active pharmaceutical ingredients (e.g., selenium sulfide, zinc pyrithione, coal tar, ketoconazole)", "Remove color from over-processed hair", "Prepare hair for chemical relaxer application", "Clarify hard-water mineral deposits from the hair"], options_es: ["Tratar condiciones específicas del cuero cabelludo como la caspa, la dermatitis seborreica o la psoriasis usando ingredientes farmacéuticos activos (p. ej., sulfuro de selenio, piritionato de zinc, alquitrán de hulla, ketoconazol)", "Eliminar el color del cabello sobreprocesado", "Preparar el cabello para la aplicación de alisador químico", "Clarificar los depósitos minerales del agua dura del cabello"], correct: 0, explanation: "Medicated shampoos contain active pharmaceutical-grade ingredients targeting scalp conditions. Common active ingredients: selenium sulfide and zinc pyrithione (anti-dandruff), coal tar (psoriasis), ketoconazole (antifungal for seborrheic dermatitis). These are over-the-counter or prescription treatments." },
  { id: 464, question: "The active ingredient most commonly found in anti-dandruff shampoos to reduce the Malassezia fungus population is:", question_es: "El ingrediente activo más comúnmente encontrado en los champús anticaspa para reducir la población del hongo Malassezia es:", options: ["Zinc pyrithione (ZPT) or selenium sulfide — both have antifungal and antibacterial properties that reduce the yeast causing dandruff", "Sodium lauryl sulfate (SLS) in high concentrations", "Glycerin combined with panthenol", "Dimethicone (silicone) as a scalp coating"], options_es: ["Piritionato de zinc (ZPT) o sulfuro de selenio — ambos tienen propiedades antifúngicas y antibacterianas que reducen la levadura que causa la caspa", "Lauril sulfato de sodio (SLS) en altas concentraciones", "Glicerina combinada con pantenol", "Dimeticona (silicona) como recubrimiento del cuero cabelludo"], correct: 0, explanation: "Zinc pyrithione and selenium sulfide are the most common active anti-dandruff ingredients. Both have antifungal properties that reduce Malassezia yeast, which is the primary cause of seborrheic dandruff. Coal tar and ketoconazole are also used for more severe cases." },
  { id: 465, question: "A 'dry shampoo' differs from regular shampoo in that:", question_es: "Un 'champú seco' difiere del champú regular en que:", options: ["It is applied to dry hair and absorbs excess oil without using water — it is a waterless cleansing option for refreshing hair between wet shampoos", "It requires less water than regular shampoo but still requires rinsing", "It contains a higher concentration of surfactants to work without lather", "It is only for use on synthetic hair extensions"], options_es: ["Se aplica al cabello seco y absorbe el exceso de aceite sin usar agua — es una opción de limpieza sin agua para refrescar el cabello entre lavados húmedos", "Requiere menos agua que el champú regular pero aún requiere enjuague", "Contiene una concentración más alta de surfactantes para funcionar sin espuma", "Es solo para uso en extensiones de cabello sintético"], correct: 0, explanation: "Dry shampoo is a waterless product (usually a powder or spray) that is applied to dry hair and absorbs excess sebum and oil at the roots. It freshens hair between wet shampooing without requiring water. Common ingredients include rice starch or silica." },
  { id: 466, question: "A protein-enriched shampoo is most beneficial for:", question_es: "Un champú enriquecido con proteínas es más beneficioso para:", options: ["Chemically damaged, over-processed, or weak hair that has lost structural integrity — the protein helps temporarily rebuild and strengthen the hair shaft", "Normal, healthy hair that needs no additional protein", "Oily hair where protein would increase sebum production", "Color-treated hair to boost the oxidation of the color molecules"], options_es: ["Cabello dañado químicamente, sobreprocesado o débil que ha perdido integridad estructural — la proteína ayuda a reconstruir y fortalecer temporalmente el eje del cabello", "Cabello normal y saludable que no necesita proteínas adicionales", "Cabello graso donde la proteína aumentaría la producción de sebo", "Cabello teñido para aumentar la oxidación de las moléculas de color"], correct: 0, explanation: "Protein-enriched shampoos contain hydrolyzed proteins (keratin, wheat, silk) that temporarily bond to damage sites on the hair shaft, filling gaps in the cuticle and cortex. They are most beneficial for chemically damaged, over-processed, or structurally weak hair." },
  { id: 467, question: "After shampooing, a conditioner should be applied primarily to:", question_es: "Después del lavado, un acondicionador debe aplicarse principalmente en:", options: ["The mid-shaft to ends of the hair — not to the scalp — unless treating a specific dry scalp condition", "The scalp and roots only, avoiding the ends", "The entire hair from roots to ends including the scalp for every conditioning treatment", "Only to the hair section that was cut to smooth the cut ends"], options_es: ["El eje medio hasta las puntas del cabello — no al cuero cabelludo — a menos que se trate una condición específica de cuero cabelludo seco", "Solo al cuero cabelludo y las raíces, evitando las puntas", "Todo el cabello de raíz a punta incluyendo el cuero cabelludo para cada tratamiento acondicionador", "Solo a la sección del cabello que fue cortada para suavizar las puntas cortadas"], correct: 0, explanation: "Conditioner is applied mid-shaft to ends — the driest, most porous areas — which benefit most from conditioning. Applying conditioner to the scalp (which produces its own oil) can cause excessive greasiness and buildup, potentially clogging follicles." },
  { id: 468, question: "An 'instant conditioner' (rinse-out conditioner) works primarily by:", question_es: "Un 'acondicionador instantáneo' (acondicionador de enjuague) funciona principalmente:", options: ["Temporarily smoothing and sealing the cuticle with conditioning agents (silicones, cetyl alcohol, cationic polymers) to improve manageability, shine, and detangling — left on for 1–5 minutes then rinsed", "Permanently restructuring the hair's disulfide bonds to reduce frizz", "Depositing pigment molecules into the cortex to enhance color vibrancy", "Deeply penetrating the cortex and remaining in the hair indefinitely"], options_es: ["Suavizando y sellando temporalmente la cutícula con agentes acondicionadores (siliconas, alcohol cetílico, polímeros catiónicos) para mejorar la manejabilidad, el brillo y el desenredo — se deja 1-5 minutos luego se enjuaga", "Reestructurando permanentemente los enlaces disulfuro del cabello para reducir el encrespamiento", "Depositando moléculas de pigmento en el córtex para mejorar la viveza del color", "Penetrando profundamente el córtex y permaneciendo en el cabello indefinidamente"], correct: 0, explanation: "Instant conditioners are rinsed out after a brief processing time (1–5 minutes). They work primarily on the cuticle surface, smoothing scales, reducing friction, and improving manageability and shine through cationic (positively charged) polymers that attract to the negatively charged hair shaft." },
  { id: 469, question: "A 'deep conditioning treatment' (penetrating conditioner) differs from an instant conditioner in that:", question_es: "Un 'tratamiento de acondicionamiento profundo' (acondicionador penetrante) difiere del acondicionador instantáneo en que:", options: ["It contains smaller molecules or active ingredients that penetrate into the cortex, is left on for 15–30 minutes (sometimes with heat), and provides more lasting repair and hydration", "It works exclusively on the cuticle surface and is rinsed out in under one minute", "It permanently alters the chemical structure of the hair through oxidation", "It is only used as a pre-chemical treatment, never for general conditioning"], options_es: ["Contiene moléculas más pequeñas o ingredientes activos que penetran en el córtex, se deja 15-30 minutos (a veces con calor) y proporciona reparación e hidratación más duraderas", "Funciona exclusivamente en la superficie de la cutícula y se enjuaga en menos de un minuto", "Altera permanentemente la estructura química del cabello a través de la oxidación", "Solo se usa como tratamiento pre-químico, nunca para acondicionamiento general"], correct: 0, explanation: "Deep (penetrating) conditioners use lower-molecular-weight proteins and moisturizers that can penetrate through the cuticle into the cortex. They require longer processing times (15–30 minutes) and may be used with gentle heat to open the cuticle for better penetration." },
  { id: 470, question: "A 'leave-in conditioner' is designed to:", question_es: "Un 'acondicionador sin enjuague' está diseñado para:", options: ["Be applied to towel-dried hair after the service and not rinsed out — it provides ongoing moisture, detangling, and protection throughout the day", "Be left in the hair during the shampoo process to pre-condition", "Replace regular shampoo for clients with very dry hair", "Be applied before shampooing to protect the hair from surfactant damage"], options_es: ["Aplicarse al cabello secado con toalla después del servicio y no enjuagarse — proporciona humedad continua, desenredo y protección durante todo el día", "Dejarse en el cabello durante el proceso de lavado para pre-acondicionar", "Reemplazar el champú regular para clientes con cabello muy seco", "Aplicarse antes del lavado para proteger el cabello del daño de los surfactantes"], correct: 0, explanation: "Leave-in conditioners are applied to clean, towel-dried hair after shampooing and conditioning and are not rinsed out. They provide ongoing moisture, detangling, frizz control, and light protection throughout the day. They are lighter formulations than rinse-out conditioners to avoid weighing the hair down." },
  { id: 471, question: "The shampoo bowl and its hardware should be disinfected:", question_es: "El lavatorio de champú y su herraje deben desinfectarse:", options: ["Between each client — thoroughly cleaned with soap and water and then disinfected with an EPA-registered disinfectant to prevent cross-contamination", "Once daily at the end of the business day only", "Only when visibly soiled with hair color or chemical product", "Weekly during a scheduled deep-clean of the barbershop"], options_es: ["Entre cada cliente — limpiados a fondo con agua y jabón y luego desinfectados con un desinfectante registrado por la EPA para prevenir la contaminación cruzada", "Una vez al día solo al final del día de negocios", "Solo cuando están visiblemente sucios con color de cabello o producto químico", "Semanalmente durante una limpieza profunda programada de la barbería"], correct: 0, explanation: "The shampoo bowl must be sanitized and disinfected between each client. Hair, scalp cells, and product residue accumulate in and around the bowl. Cross-contamination through an unclean bowl can transmit scalp conditions or pathogens between clients." },
  { id: 472, question: "The reclined (recumbent) shampoo position at the shampoo bowl:", question_es: "La posición reclinada en el lavatorio de champú:", options: ["Has the client leaning back with their neck resting in the bowl cradle — it is the standard barbershop shampoo position and provides good access to the scalp", "Has the client leaning forward over the bowl, which is standard in most barbershops", "Requires the client to hold their own head up throughout the entire service", "Is only used for elderly or disabled clients who cannot lean forward"], options_es: ["El cliente se recuesta con el cuello apoyado en la curvatura del lavatorio — es la posición estándar de lavado en barberías y proporciona buen acceso al cuero cabelludo", "El cliente se inclina hacia adelante sobre el lavatorio, que es estándar en la mayoría de las barberías", "Requiere que el cliente sostenga su propia cabeza durante todo el servicio", "Solo se usa para clientes de edad avanzada o discapacitados que no pueden inclinarse hacia adelante"], correct: 0, explanation: "The reclined position (neck in the bowl cradle, client leaning back) is the standard shampoo position in most barbershops. It allows the barber to control the water flow, provides good access to all areas of the scalp, and is generally more comfortable for the client." },
  { id: 473, question: "After rinsing out the shampoo, the barber should check:", question_es: "Después de enjuagar el champú, el barbero debe verificar:", options: ["That all shampoo is fully rinsed out — shampoo residue left on the scalp or hair causes buildup, irritation, itching, and an unpleasant feeling after drying", "Whether to apply a second round of shampoo in every case", "The client's final hair color result after the cleansing step", "That the scalp temperature has returned to normal after the warm water"], options_es: ["Que todo el champú se haya enjuagado completamente — el residuo de champú dejado en el cuero cabelludo o el cabello causa acumulación, irritación, picazón y una sensación desagradable después del secado", "Si se debe aplicar una segunda ronda de champú en cada caso", "El resultado de color final del cabello del cliente después del paso de limpieza", "Que la temperatura del cuero cabelludo haya vuelto a la normalidad después del agua tibia"], correct: 0, explanation: "Thorough rinsing is critical. Shampoo residue left behind causes scalp irritation, itching, dullness, and product buildup. The barber should run fingers through the hair to confirm all traces of shampoo lather are rinsed away before proceeding." },
  { id: 474, question: "Towel-blotting hair after shampooing (versus vigorous rubbing) is recommended because:", question_es: "Secar el cabello con palmaditas de toalla después del lavado (en lugar de frotar vigorosamente) se recomienda porque:", options: ["Wet hair is in its most fragile state — the hydrogen bonds are broken and the cuticle is raised, making it highly susceptible to mechanical damage and breakage from vigorous rubbing", "Rubbing creates excessive static electricity that interferes with styling", "Vigorous rubbing removes too much sebum that was not removed during shampooing", "TDLR regulations require blotting and prohibit rubbing motions during towel drying"], options_es: ["El cabello mojado está en su estado más frágil — los enlaces de hidrógeno están rotos y la cutícula está levantada, haciéndolo muy susceptible al daño mecánico y la rotura por el frotamiento vigoroso", "Frotar crea electricidad estática excesiva que interfiere con el peinado", "El frotamiento vigoroso elimina demasiado sebo que no fue eliminado durante el lavado", "Las regulaciones de TDLR requieren palmaditas y prohíben los movimientos de frotamiento durante el secado con toalla"], correct: 0, explanation: "Wet hair has its hydrogen bonds temporarily broken, making it weak and elastic. The raised cuticle is easily disrupted by friction. Vigorous rubbing creates breakage and frizz. Gentle blotting absorbs excess water without causing mechanical damage to the fragile wet hair structure." },
  { id: 475, question: "A 'scalp treatment' or 'pre-shampoo oil treatment' applied before shampooing is intended to:", question_es: "Un 'tratamiento del cuero cabelludo' o 'tratamiento de aceite pre-champú' aplicado antes del lavado está destinado a:", options: ["Nourish and condition a dry or damaged scalp and hair, and may help loosen stubborn product buildup or scale before cleansing", "Permanently eliminate dandruff from the scalp", "Protect the hair from the surfactants in the shampoo by forming a barrier", "Open the hair follicle wider for better shampoo penetration"], options_es: ["Nutrir y acondicionar un cuero cabelludo o cabello seco o dañado, y puede ayudar a aflojar la acumulación de productos o escamas difíciles antes de la limpieza", "Eliminar permanentemente la caspa del cuero cabelludo", "Proteger el cabello de los surfactantes en el champú formando una barrera", "Abrir el folículo piloso más ampliamente para una mejor penetración del champú"], correct: 0, explanation: "Pre-shampoo oil treatments (hot oil treatments, scalp oils) are applied before shampooing to nourish the scalp, soften the hair, and help break down buildup. They are especially beneficial for dry, damaged, or tightly coiled hair types. They are then removed during the shampoo step." },
  { id: 476, question: "For a client with an oily scalp, the barber should recommend:", question_es: "Para un cliente con cuero cabelludo graso, el barbero debe recomendar:", options: ["A balancing or clarifying shampoo designed for oily hair — gentle degreasing without overly stripping, which could trigger rebound oil production", "A heavy moisturizing shampoo to balance dryness caused by excess oil production", "A protein treatment to strengthen the hair and slow oil production", "Washing with only water and skipping shampoo to preserve natural oils"], options_es: ["Un champú equilibrante o clarificante diseñado para cabello graso — desengrasante suave sin eliminar excesivamente, lo que podría desencadenar una producción de aceite de rebote", "Un champú humectante pesado para equilibrar la sequedad causada por la producción excesiva de aceite", "Un tratamiento de proteínas para fortalecer el cabello y ralentizar la producción de aceite", "Lavar solo con agua y omitir el champú para preservar los aceites naturales"], correct: 0, explanation: "Oily scalp clients benefit from balancing or gentle clarifying shampoos designed to remove excess sebum without over-stripping. Over-stripping with harsh shampoos triggers the scalp to produce MORE oil as a compensatory response — making oiliness worse." },
  { id: 477, question: "Using the same shampoo towel on multiple clients without laundering is:", question_es: "Usar la misma toalla de champú en múltiples clientes sin lavarla es:", options: ["A sanitation violation that creates a vehicle for cross-contamination and transmission of pathogens, parasites, or communicable scalp conditions between clients", "Acceptable as long as the towel is shaken out between clients", "Permitted if the towel is sprayed with barbicide between uses", "Only prohibited if the first client had a known skin condition"], options_es: ["Una violación de saneamiento que crea un vehículo para la contaminación cruzada y transmisión de patógenos, parásitos o condiciones contagiosas del cuero cabelludo entre clientes", "Aceptable siempre que la toalla se sacuda entre clientes", "Permitido si la toalla se rocía con barbicida entre usos", "Solo prohibido si el primer cliente tenía una condición cutánea conocida"], correct: 0, explanation: "Each client must receive freshly laundered towels. Reusing towels between clients transmits bacteria, fungi, viruses, or parasites (lice) from one client to another. This is a fundamental sanitation requirement enforced by TDLR inspections." },
  { id: 478, question: "The correct amount of shampoo to apply for a typical haircut-length service is:", question_es: "La cantidad correcta de champú para aplicar en un servicio de longitud típica de corte de cabello es:", options: ["A small amount (dime to quarter size) distributed evenly — excess shampoo does not improve cleansing and requires extra rinsing time", "As much shampoo as needed to create a very thick, heavy lather throughout all the hair at once", "The same amount as is used for full-length, below-shoulder hair", "Shampoo should be poured directly from the bottle without measuring"], options_es: ["Una pequeña cantidad (tamaño de moneda de 10 a 25 centavos) distribuida uniformemente — el exceso de champú no mejora la limpieza y requiere tiempo de enjuague extra", "Tanta cantidad de champú como sea necesario para crear una espuma muy espesa y abundante en todo el cabello a la vez", "La misma cantidad que se usa para el cabello de longitud completa, por debajo de los hombros", "El champú debe verterse directamente de la botella sin medir"], correct: 0, explanation: "For short to medium hair (typical barbershop client), a small amount of shampoo is sufficient. More shampoo does not clean better — it just requires more water and time to rinse. Professional dispensing helps control product usage and reduces waste." },
  { id: 479, question: "An 'acid rinse' (acidic rinse) applied after shampooing serves to:", question_es: "Un 'enjuague ácido' (enjuague acidificante) aplicado después del lavado sirve para:", options: ["Lower the pH back toward the hair's natural acidic range, smoothing and closing the cuticle after the slightly alkaline shampoo has raised it", "Raise the pH to open the cuticle for better conditioner penetration", "Remove any remaining conditioner from the hair after the conditioning step", "Deposit artificial color pigments onto the hair shaft"], options_es: ["Reducir el pH de vuelta hacia el rango ácido natural del cabello, suavizando y cerrando la cutícula después de que el champú ligeramente alcalino la haya levantado", "Elevar el pH para abrir la cutícula para una mejor penetración del acondicionador", "Eliminar cualquier acondicionador restante del cabello después del paso de acondicionamiento", "Depositar pigmentos de color artificial en el eje del cabello"], correct: 0, explanation: "Acid (acidifying) rinses contain diluted acids (lemon juice, apple cider vinegar, citric acid) or are formulated at a low pH. After a slightly alkaline shampoo, an acid rinse restores the hair's natural acidic pH (4.5–5.5), smoothing the cuticle for added shine and reducing tangling." },
  { id: 480, question: "A barber should recommend professional shampoo products to clients over retail (drugstore) products because:", question_es: "Un barbero debe recomendar productos de champú profesionales a los clientes en lugar de productos de venta al público (farmacia) porque:", options: ["Professional products are formulated at higher concentrations with better ingredients, are pH-balanced for hair health, and are matched to specific hair types and conditions — the barber can make a customized recommendation based on the client's scalp and hair analysis", "Professional shampoos contain the same formula as drugstore brands — the only difference is the price", "TDLR requires barbers to only sell products from approved vendors", "Retail shampoos are illegal to use in Texas barbershops"], options_es: ["Los productos profesionales están formulados con concentraciones más altas con mejores ingredientes, tienen un pH equilibrado para la salud del cabello y están adaptados a tipos y condiciones específicas de cabello — el barbero puede hacer una recomendación personalizada basada en el análisis del cuero cabelludo y el cabello del cliente", "Los champús profesionales contienen la misma fórmula que las marcas de farmacia — la única diferencia es el precio", "TDLR requiere que los barberos solo vendan productos de vendedores aprobados", "Los champús de venta al público son ilegales de usar en las barberías de Texas"], correct: 0, explanation: "Professional shampoos are often more concentrated, contain fewer harsh detergents (less SLS), are better pH-balanced, and are formulated for specific hair conditions. A barber can provide personalized guidance matching the right professional product to the client's specific scalp and hair needs." },
  { id: 481, question: "The barber's ergonomic positioning at the shampoo bowl is important because:", question_es: "La posición ergonómica del barbero en el lavatorio de champú es importante porque:", options: ["Proper posture and positioning prevent occupational injuries (back strain, wrist injury, neck pain) during the repetitive motions of shampooing performed throughout the workday", "TDLR requires barbers to maintain a specific stance during shampoo services for safety compliance", "Ergonomic positioning affects the effectiveness of the shampoo product's cleansing action", "The client's comfort depends entirely on the barber's foot position at the bowl"], options_es: ["La postura y el posicionamiento correctos previenen lesiones ocupacionales (dolor de espalda, lesión de muñeca, dolor de cuello) durante los movimientos repetitivos del lavado realizados durante toda la jornada laboral", "TDLR requiere que los barberos mantengan una postura específica durante los servicios de champú para cumplimiento de seguridad", "El posicionamiento ergonómico afecta la efectividad de la acción de limpieza del producto de champú", "La comodidad del cliente depende completamente de la posición de los pies del barbero en el lavatorio"], correct: 0, explanation: "Barbers perform shampooing services repeatedly throughout the day. Poor ergonomics (bending at the waist, awkward wrist positions, twisting) cause cumulative trauma and occupational injuries to the back, shoulders, wrists, and neck. Proper body mechanics protect the barber's long-term physical health and career." },
]

